// Prepare data for Gemini Image node
const input = $('Webhook').first().json;
const body = input.body || input;

// Get operation from request (default: generate)
const operation = body.operation || 'generate';

// Common parameters
const aspectRatio = body.aspectRatio || '16:9';
const outputFormat = body.outputFormat || 'png';
const model = body.model || 'gemini-2.5-flash-preview-native-audio-dialog';
const includeTextFeedback = body.includeTextFeedback === true || body.includeTextFeedback === 'true';

// GCS upload parameters
const uploadToGcs = body.uploadToGcs === true || body.uploadToGcs === 'true';
const gcsBucket = body.gcsBucket || '';
const gcsPathPrefix = body.gcsPathPrefix || 'gemini-images';
const signedUrlExpirationHours = body.signedUrlExpirationHours || 24;
const userId = body.userId || '';

// Operation-specific parameters
const result = {
  operation,
  aspectRatio,
  outputFormat,
  model,
  includeTextFeedback,
  uploadToGcs,
  gcsBucket,
  gcsPathPrefix,
  signedUrlExpirationHours,
  userId,
  originalRequest: { ...body }
};

switch (operation) {
  case 'generate':
    result.prompt = body.prompt || '';
    break;

  case 'extractCharacter':
    result.sourceImage = body.sourceImage || '';
    result.sourceImageMimeType = body.sourceImageMimeType || 'image/png';
    result.characterDescription = body.characterDescription || 'the main character';
    break;

  case 'createCharacterSheet':
    result.sourceImage = body.sourceImage || '';
    result.sourceImageMimeType = body.sourceImageMimeType || 'image/png';
    result.views = body.views || ['front', 'back'];
    break;

  case 'composeScene':
    result.referenceImages = body.referenceImages || [];
    result.scenePrompt = body.scenePrompt || '';
    break;
}

return [{ json: result }];

// Format response
const input = $input.first().json;
const binary = $input.first().binary;

const response = {
  success: true,
  operation: input.operation,
  image: {
    base64: input.imageBase64,
    mimeType: input.mimeType,
    format: input.mimeType.split('/')[1]
  },
  model: input.model,
  textFeedback: input.textFeedback || null,
  metadata: input.metadata
};

// Add GCS info if present
if (input.gcs) {
  response.gcs = input.gcs;
}

return [{ json: response }];
